-- Round-12 §1A — idempotent seed-defaults migration.
--
-- Runs on every `prisma migrate deploy`. Inserts the floor-row set
-- a usable BreakFix Triage instance needs (8 EmailTemplate rows,
-- 1 example EmailRule, 33 Holiday rows for 2026-2028).
--
-- Idempotency strategy:
--   - EmailTemplate: ON CONFLICT (key) DO NOTHING
--   - EmailRule: WHERE NOT EXISTS (...) on (scope, event, templateId)
--   - Holiday: WHERE NOT EXISTS (...) on (date, scope, scopeId)
--
-- Dates were generated by src/lib/holidays/federal.ts +
-- prisma/lib/federal-holidays.ts (lockstep-pinned). Regenerate
-- annually as 2029+ comes into scope.
--
-- Audit rows: every insert writes an AuditLog with action =
-- 'system_seed' and after JSON containing { source: 'migration',
-- seededAt: now() }. The audit trail is the canonical "is this row
-- seeded or operator-added" answer per the §1A spec.

-- =====================================================================
-- EmailTemplate seeds
-- =====================================================================

INSERT INTO "EmailTemplate" ("id", "key", "subject", "bodyHtml", "bodyText", "variables", "createdAt", "updatedAt")
VALUES
  (
    'seed_tpl_ticket_created',
