    'A new ticket was created for {{school.name}}: {{ticket.summary}}. Open: {{link}}',
    '{"type":"object","required":["ticket","school","link"],"properties":{"ticket":{"type":"object"},"school":{"type":"object"},"link":{"type":"string"}}}',
    NOW(), NOW()
  ),
  (
    'seed_tpl_ticket_assigned',
