    '{"type":"object","required":["ticket","assignee","link"],"properties":{"ticket":{"type":"object"},"assignee":{"type":"object"},"link":{"type":"string"}}}',
    NOW(), NOW()
  ),
  (
    'seed_tpl_ticket_status_changed',
