    'Ticket {{ticket.number}} now {{ticket.state}}',
    '<p>{{ticket.number}} moved to <strong>{{ticket.state}}</strong>.</p><p><a href="{{link}}">Open ticket</a></p>',
    'Ticket {{ticket.number}} moved to {{ticket.state}}. Open: {{link}}',
    '{"type":"object","required":["ticket","link"],"properties":{"ticket":{"type":"object"},"link":{"type":"string"}}}',
    NOW(), NOW()
  ),
  (
    'seed_tpl_quote_sent',
    'quote_sent',
    'Quote {{quote.number}} for ticket {{ticket.number}}',
    '<p>A repair quote is ready for ticket {{ticket.number}}.</p><p>Total: {{quote.total}}</p><p><a href="{{link}}">Review and approve</a></p>',
    'Quote ready for {{ticket.number}}. Total: {{quote.total}}. Review: {{link}}',
    '{"type":"object","required":["ticket","quote","link"],"properties":{"ticket":{"type":"object"},"quote":{"type":"object"},"link":{"type":"string"}}}',
    NOW(), NOW()
  ),
  (
    'seed_tpl_daily_digest',
    'daily_digest',
    'BreakFix Triage daily digest — {{date}}',
    '<p>Daily summary for {{date}}.</p><p>Open tickets: {{counts.open}}</p><p>Awaiting parts: {{counts.parts}}</p><p>Approaching SLA: {{counts.sla}}</p>',
    'Daily summary for {{date}}. Open: {{counts.open}}. Awaiting parts: {{counts.parts}}. Approaching SLA: {{counts.sla}}.',
    '{"type":"object","required":["date","counts"],"properties":{"date":{"type":"string"},"counts":{"type":"object"}}}',
    NOW(), NOW()
  ),
  (
    'seed_tpl_delivery_scheduled',
    'delivery_scheduled',
    'Delivery scheduled for ticket {{ticket.number}}',
