    'sla_breach_warning',
    'SLA approaching for ticket {{ticket.number}}',
    '<p>{{ticket.number}} is approaching its SLA threshold ({{sla.threshold}} days).</p>',
    'SLA approaching for {{ticket.number}} ({{sla.threshold}} days).',
    '{"type":"object","required":["ticket","sla"],"properties":{"ticket":{"type":"object"},"sla":{"type":"object"}}}',
    NOW(), NOW()
  ),
  (
    'seed_tpl_ticket_closed',
    'ticket_closed',
