ON CONFLICT ("key") DO NOTHING;

-- Audit rows for each EmailTemplate seed insert.
INSERT INTO "AuditLog" ("id", "actorUserId", "entityType", "entityId", "action", "after", "createdAt")
SELECT
  'seed_audit_tpl_' || t."key",
  NULL,
  'EmailTemplate',
  t."id",
  'system_seed',
  jsonb_build_object('source', 'migration', 'seededAt', NOW()::text, 'key', t."key"),
  NOW()
FROM "EmailTemplate" t
WHERE t."id" LIKE 'seed_tpl_%'
  AND NOT EXISTS (
    SELECT 1 FROM "AuditLog" a
    WHERE a."entityType" = 'EmailTemplate'
      AND a."entityId" = t."id"
      AND a."action" = 'system_seed'
  );

-- =====================================================================
-- EmailRule seeds — one example Global rule on ticket_created.
-- Disabled by default per Round-5 §1 contract; admins opt-in.
-- =====================================================================

INSERT INTO "EmailRule" ("id", "scope", "scopeId", "event", "recipients", "templateId", "enabled", "createdAt", "updatedAt")
SELECT
  'seed_rule_ticket_created_global',
  'GLOBAL',
  NULL,
  'ticket_created',
  '{"to":[{"kind":"school_spoc"},{"kind":"ticket_reporter"}],"cc":[{"kind":"wynndalco_team"}],"bcc":[]}'::jsonb,
  'seed_tpl_ticket_created',
  FALSE,
  NOW(),
  NOW()
WHERE NOT EXISTS (
  SELECT 1 FROM "EmailRule"
  WHERE "scope" = 'GLOBAL' AND "event" = 'ticket_created' AND "templateId" = 'seed_tpl_ticket_created'
);

INSERT INTO "AuditLog" ("id", "actorUserId", "entityType", "entityId", "action", "after", "createdAt")
SELECT
  'seed_audit_rule_ticket_created',
  NULL,
  'EmailRule',
  'seed_rule_ticket_created_global',
  'system_seed',
  jsonb_build_object('source', 'migration', 'seededAt', NOW()::text, 'event', 'ticket_created'),
  NOW()
WHERE EXISTS (SELECT 1 FROM "EmailRule" WHERE "id" = 'seed_rule_ticket_created_global')
  AND NOT EXISTS (
    SELECT 1 FROM "AuditLog"
    WHERE "entityType" = 'EmailRule'
      AND "entityId" = 'seed_rule_ticket_created_global'
      AND "action" = 'system_seed'
  );

-- =====================================================================
-- Holiday seeds — 11 federal holidays × 3 years (2026, 2027, 2028).
-- Dates verified against src/lib/holidays/federal.ts. Regenerate
-- annually as 2029+ comes into scope (add a new migration).
-- =====================================================================

INSERT INTO "Holiday" ("id", "date", "label", "scope", "scopeId", "createdAt")
SELECT id, date::date, label, 'GLOBAL'::"HolidayScope", NULL, NOW()
FROM (VALUES
  -- 2026
  ('seed_hol_2026_new_year', '2026-01-01', 'New Year''s Day'),
  ('seed_hol_2026_mlk', '2026-01-19', 'Martin Luther King Jr. Day'),
  ('seed_hol_2026_washington', '2026-02-16', 'Washington''s Birthday'),
  ('seed_hol_2026_memorial', '2026-05-25', 'Memorial Day'),
  ('seed_hol_2026_juneteenth', '2026-06-19', 'Juneteenth'),
  ('seed_hol_2026_independence', '2026-07-04', 'Independence Day'),
  ('seed_hol_2026_labor', '2026-09-07', 'Labor Day'),
  ('seed_hol_2026_columbus', '2026-10-12', 'Columbus Day'),
  ('seed_hol_2026_veterans', '2026-11-11', 'Veterans Day'),
  ('seed_hol_2026_thanksgiving', '2026-11-26', 'Thanksgiving Day'),
  ('seed_hol_2026_christmas', '2026-12-25', 'Christmas Day'),
  -- 2027
  ('seed_hol_2027_new_year', '2027-01-01', 'New Year''s Day'),
  ('seed_hol_2027_mlk', '2027-01-18', 'Martin Luther King Jr. Day'),
  ('seed_hol_2027_washington', '2027-02-15', 'Washington''s Birthday'),
  ('seed_hol_2027_memorial', '2027-05-31', 'Memorial Day'),
  ('seed_hol_2027_juneteenth', '2027-06-19', 'Juneteenth'),
  ('seed_hol_2027_independence', '2027-07-04', 'Independence Day'),
  ('seed_hol_2027_labor', '2027-09-06', 'Labor Day'),
  ('seed_hol_2027_columbus', '2027-10-11', 'Columbus Day'),
  ('seed_hol_2027_veterans', '2027-11-11', 'Veterans Day'),
  ('seed_hol_2027_thanksgiving', '2027-11-25', 'Thanksgiving Day'),
  ('seed_hol_2027_christmas', '2027-12-25', 'Christmas Day'),
  -- 2028
  ('seed_hol_2028_new_year', '2028-01-01', 'New Year''s Day'),
  ('seed_hol_2028_mlk', '2028-01-17', 'Martin Luther King Jr. Day'),
  ('seed_hol_2028_washington', '2028-02-21', 'Washington''s Birthday'),
  ('seed_hol_2028_memorial', '2028-05-29', 'Memorial Day'),
  ('seed_hol_2028_juneteenth', '2028-06-19', 'Juneteenth'),
  ('seed_hol_2028_independence', '2028-07-04', 'Independence Day'),
  ('seed_hol_2028_labor', '2028-09-04', 'Labor Day'),
  ('seed_hol_2028_columbus', '2028-10-09', 'Columbus Day'),
  ('seed_hol_2028_veterans', '2028-11-11', 'Veterans Day'),
  ('seed_hol_2028_thanksgiving', '2028-11-23', 'Thanksgiving Day'),
  ('seed_hol_2028_christmas', '2028-12-25', 'Christmas Day')
) AS new_holidays(id, date, label)
WHERE NOT EXISTS (
  SELECT 1 FROM "Holiday" h
  WHERE h."date" = new_holidays.date::date
    AND h."scope" = 'GLOBAL'
    AND h."scopeId" IS NULL
);

-- Audit rows for each Holiday seed insert.
INSERT INTO "AuditLog" ("id", "actorUserId", "entityType", "entityId", "action", "after", "createdAt")
SELECT
  'seed_audit_hol_' || h."id",
  NULL,
  'Holiday',
  h."id",
  'system_seed',
  jsonb_build_object('source', 'migration', 'seededAt', NOW()::text, 'date', h."date"::text, 'label', h."label"),
  NOW()
FROM "Holiday" h
WHERE h."id" LIKE 'seed_hol_%'
  AND NOT EXISTS (
    SELECT 1 FROM "AuditLog" a
    WHERE a."entityType" = 'Holiday'
      AND a."entityId" = h."id"
      AND a."action" = 'system_seed'
  );
